function crmSaveC(id){const v=n=>(document.getElementById(n)||{value:''}).value.trim();if(!v('cn1'))return toast('Enter a name.');const o={name:v('cn1'),phone:crmFmtPhone(v('cp'))||v('cp'),email:v('ce'),age:v('ca'),src:v('cs')},fu=v('cf'),st=v('cst');
 if(id){const c=crmGet(id);if(!c)return closeM();crmPut(id,o);if(st&&CRM_N2L[c.stage]!==st)crmStage(id,CRM_L2N[st]||'new','edited');crmSetFuDate(id,fu);closeM();go();return}
 const d=crmFindDup(o,crmDupIndex(crmAll()));const make=()=>{const c=crmCreate(Object.assign(o,{stage:CRM_L2N[st]||'new'}),{noTask:!!fu});if(fu)crmSetFuDate(c.id,fu);cid=c.id;closeM();go()};
 if(d)return ask('This looks like a duplicate of '+esc(d.c.name)+' ('+esc(d.why)+'). Add anyway?',make);make()}
function crmSetFuDate(id,fu){const cur=crmOpenTasks(id).filter(t=>t.ty==='fu'||t.r==='legacy');if(!fu){cur.forEach(t=>crmTaskPatch(t.id,{s:'d',dn:Date.now(),dby:WHO}));return}if(cur.some(t=>crmDay(t.due)===fu))return;cur.forEach(t=>crmTaskPatch(t.id,{s:'x',dn:Date.now()}));const c=crmGet(id);crmTask({id:'fu_'+id+'_'+fu.replace(/-/g,''),c:id,ty:'fu',t:'Follow-up',due:crmAt(fu,9,0),ad:1,ow:c?c.owner:WHO,r:'man'})}
function crmAddN(id){const x=document.getElementById('nx'),ty=(document.getElementById('nt')||{}).value||'Note';if(!x||!x.value.trim())return toast('Type a note first.');crmEv(id,{Call:'call',Text:'text',Email:'email',Meeting:'meet',Note:'note'}[ty]||'note',{t:x.value.trim()});go()}
function crmSetSt(id,v){const c=crmGet(id);if(c&&CRM_N2L[c.stage]!==v)crmStage(id,CRM_L2N[v]||'new','legacy select');go()}
function crmDelN(id,i){const n=(crmMy().find(x=>x.id==id)||{notes:[]}).notes[i];if(n&&n._e)crmEvDel(n._e);else go()}
function crmDelC(id){crmDelAsk(id)}
function crmClearFu(id){const t=crmNext(id);if(t){crmDone(t.id)}go();toast('Follow-up cleared',1)}
function crmCiSet(id,k,v){const map={marital:'info.marital',occ:'info.occ',tobacco:'info.tobacco',pref:'info.pref',best:'info.best',bname:'info.bname',brel:'info.brel',bphone:'info.bphone',ename:'info.ename',ephone:'info.ephone'};crmField(id,map[k]||k,String(v))}
function crmMbPin(c,fresh){if(!c)return;const cur=(crmGet(c.id)||{}).mb||{};if(!fresh&&cur.pin)return;const pin=String(Math.floor(1000+Math.random()*9000));crmPut(c.id,{mb:{pin}});c.mb=Object.assign({},c.mb||{},{pin});if(fresh){const e=document.getElementById('mbf_pin');if(e)e.value=pin;mbUpdate()}}
function crmMbSet(k,v){const c=mbClient();if(!c)return;c.mb=c.mb||{};if(v==='')delete c.mb[k];else c.mb[k]=v;crmPut(c.id,{mb:{[k]:v===''?null:v}});
 if(k==='initial'){const r=document.getElementById('mbf_recurring');if(r&&c.mb.recurring===undefined)r.value=mbVal(c,'recurring')}mbUpdate()}
function crmMbLog(){const c=mbClient(),o=document.getElementById('mbo');if(!c||!o||!o.value.trim())return toast('Choose a client and write a message first.');const k=document.getElementById('mbk');crmEv(c.id,{Text:'text',Email:'email',Note:'note'}[(k&&k.value)||'Text']||'text',{t:'Message sent:\n'+o.value});toast('Saved to '+c.name+"'s timeline",1)}
function crmSimLead(){const pk=a=>a[Math.floor(Math.random()*a.length)],ri=(a,b)=>a+Math.floor(Math.random()*(b-a+1)),name=pk(SFN)+' '+pk(SLN),s=pk(CRM_SRC.slice(0,4)),st=pk(['PA','OH','WV','NY','FL']);
 const c=crmCreate({name,phone:'412-555-'+ri(1000,9999),email:name.toLowerCase().replace(' ','.')+'@example.com',age:String(ri(38,74)),state:st,prod:pk(['Final Expense','Mortgage Protection','Term']),src:s,owner:WHO},{note:'Inbound lead from '+s+'. Call within five minutes.'});
 pushAlert({k:'crmn-'+c.id,sev:'info',t:'New lead',m:`${name} from ${s} needs a first call`,go:['Clients','',c.id]})}
function crmCmds(L){if(!crmOn())return;L.push(['New lead','Clients',()=>crmNewLead()],['Open Today','Clients',()=>{cid=null;openTab('Clients','Today')}],['Call next lead','Clients',crmCallNext],['Open pipeline','Clients',()=>{cid=null;openTab('Clients','Pipeline')}],['Import leads','Clients',()=>{cid=null;openTab('Clients','Today');crmImport()}])}
